-- What an authorized contact provider reported about a person on each refresh (company, title, employment status as the provider states it): the evidence behind DEPARTURE signals.
create table careercloud.contact_snapshots (
  id                     text primary key check (id ~ '^csn_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  contact_id             text not null check (char_length(contact_id) <= 40),
  provider               text not null default 'zoominfo' check (provider in ('zoominfo', 'seamless', 'manual')),
  provider_contact_id    text check (char_length(provider_contact_id) <= 200),
  company_id             text check (char_length(company_id) <= 40),
  company_name           text check (char_length(company_name) <= 300),
  title                  text check (char_length(title) <= 300),
  employment_status      text not null default 'unknown' check (employment_status in ('current', 'left_company', 'unknown')),
  observed_at            timestamptz not null,
  evidence               jsonb not null default '{}'::jsonb
);

create index contact_snapshots_by_ws_created on careercloud.contact_snapshots (workspace_id, created_at desc, id desc);
create index contact_snapshots_by_ws_contact_id on careercloud.contact_snapshots (workspace_id, contact_id);
create index contact_snapshots_by_ws_provider on careercloud.contact_snapshots (workspace_id, provider);
create index contact_snapshots_by_ws_provider_contact_id on careercloud.contact_snapshots (workspace_id, provider_contact_id);
create index contact_snapshots_by_ws_employment_status on careercloud.contact_snapshots (workspace_id, employment_status);
create trigger contact_snapshots_guard before update on careercloud.contact_snapshots
  for each row execute function careercloud.guard_platform_row();
alter table careercloud.contact_snapshots enable row level security;
create policy contact_snapshots_select on careercloud.contact_snapshots for select to authenticated
  using (careercloud.is_member(workspace_id));
create policy contact_snapshots_insert on careercloud.contact_snapshots for insert to authenticated
  with check (careercloud.can_write(workspace_id) and created_by = auth.uid());
grant select, insert on careercloud.contact_snapshots to authenticated;

