-- Closed loop: what happened after a signal produced a prospect/campaign (contacted, replied, meeting, opportunity, no response, disqualified), linked to the signal, company, prospect and campaign.
create table careercloud.signal_outcomes (
  id                     text primary key check (id ~ '^so_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  signal_id              text not null check (char_length(signal_id) <= 40),
  company_id             text check (char_length(company_id) <= 40),
  contact_id             text check (char_length(contact_id) <= 40),
  campaign_id            text check (char_length(campaign_id) <= 40),
  enrollment_id          text check (char_length(enrollment_id) <= 40),
  opportunity_id         text check (char_length(opportunity_id) <= 40),
  outcome                text not null default 'contacted' check (outcome in ('contacted', 'replied', 'meeting', 'opportunity', 'no_response', 'disqualified')),
  occurred_at            timestamptz not null,
  source                 text not null default 'message_event' check (source in ('message_event', 'enrollment', 'opportunity', 'manual')),
  note                   text check (char_length(note) <= 2000),
  data                   jsonb not null default '{}'::jsonb
);

create index signal_outcomes_by_ws_created on careercloud.signal_outcomes (workspace_id, created_at desc, id desc);
create index signal_outcomes_by_ws_signal_id on careercloud.signal_outcomes (workspace_id, signal_id);
create index signal_outcomes_by_ws_company_id on careercloud.signal_outcomes (workspace_id, company_id);
create index signal_outcomes_by_ws_contact_id on careercloud.signal_outcomes (workspace_id, contact_id);
create index signal_outcomes_by_ws_campaign_id on careercloud.signal_outcomes (workspace_id, campaign_id);
create index signal_outcomes_by_ws_enrollment_id on careercloud.signal_outcomes (workspace_id, enrollment_id);
create index signal_outcomes_by_ws_outcome on careercloud.signal_outcomes (workspace_id, outcome);
create index signal_outcomes_by_ws_source on careercloud.signal_outcomes (workspace_id, source);
create trigger signal_outcomes_guard before update on careercloud.signal_outcomes
  for each row execute function careercloud.guard_platform_row();
alter table careercloud.signal_outcomes enable row level security;
create policy signal_outcomes_select on careercloud.signal_outcomes for select to authenticated
  using (careercloud.is_member(workspace_id));
create policy signal_outcomes_insert on careercloud.signal_outcomes for insert to authenticated
